    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_xingce_data_rank_proportion'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '比重类排序', 'kp-xingce-data-rank-proportion', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "比重类排序"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "同分母比重比较，等效转化为分子直接比较。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "题目要求对多个部分占同一个整体的比重进行排序。如：“2023年，江苏、浙江、广东占全国GDP的比重由高到低排序”。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "既然是“占全国GDP”，说明它们的分母 B 是同一个数字。"}]}, {"type": "katexBlock", "attrs": {"content": "\\frac{A_1}{B} \\text{ vs } \\frac{A_2}{B} \\quad \\Rightarrow \\quad \\text{直接比较 } A_1 \\text{ 和 } A_2"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[阅读题目找出待排比重] --> B{这几个比重的分母是否一样?}\nB -- 是一样的(如占同一省份总数) --> C[忽略分母, 直接去材料找分子的原始数据]\nB -- 不一样(跨省跨领域) --> D[进入常规的分数比较法则]\nC --> E[将分子原始数据按'直接比较法'排序]\nD --> F[运用大大则大或差分法排序]\nE --> G[对应选项选出答案]\nF --> G"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题完整推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 2023年某市三大产业产值：一产100亿，二产500亿，三产400亿。求这三大产业占全市GDP的比重排序？"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "判定类型：都是占“全市GDP”的比重，分母完全相同。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "忽略分母：不用去算全市GDP等于100+500+400=1000亿，更不用去算比重（10%, 50%, 40%）。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "直接比分子：二产(500) > 三产(400) > 一产(100)。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "锁定答案：比重排序直接就是 二产 > 三产 > 一产。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "强行算基期比重：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "如果题目问“2022年（基期）的比重排序”。由于上一年的全市总GDP也是同一个分母，你同样可以！只需要把这三个产业的基期量算出来比较就行，绝对不需要去求全市总基期量再做除法！"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "六、刷题建议"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "看到同级分类的占比排序，要在脑子里自动过滤掉“占XX的比重”这句话，把它当成纯正的绝对量比较题来做。"}]}]}$$ AS jsonb), NULL, '比重类排序的核心考点与实战推导。', category_node.id, CAST('["资料分析", "比重类排序"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_data_rank_proportion", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
